3	
4	import "sort"
5	
6	// Intent is one payment request from an account abstraction wallet.
7	type Intent struct {
8		ID        string
9		Account   string
10		Paymaster string
11		Amount    int64
12		Asset     string
13		Nonce     uint64
14		State     string
15	}
