17	// Settlement is the ledger effect of executing an intent.
18	type Settlement struct {
19		Intent  string
20		Charged int64
21		FeeBps  int
22		Ref     string
23		Status  string
24		Reason  string
25	}
26	
27	// Execute applies fee policy and enforces per-intent idempotency.
28	func Execute(intent Intent, feeBps int, spent map[string]bool, balance int64) Settlement {
29		if intent.State != "pending" {
30			return Settlement{Intent: intent.ID, Status: "rejected", Reason: "intent is not pending"}
31		}
32		if spent[intent.ID] {
33			return Settlement{Intent: intent.ID, Status: "rejected", Reason: "duplicate settlement attempt"}
34		}
35		fee := intent.Amount * int64(feeBps) / 10000
36		total := intent.Amount + fee
37		if total > balance {
38			return Settlement{Intent: intent.ID, Status: "failed", Reason: "insufficient balance for amount plus fee"}
39		}
40		spent[intent.ID] = true
41		return Settlement{Intent: intent.ID, Charged: total, FeeBps: feeBps, Ref: "settle:" + intent.ID, Status: "settled"}
42	}
43	
44	// Reconcile reports intents with no matching settlement, in stable order.
45	func Reconcile(intents []Intent, settlements []Settlement) []string {
46		seen := map[string]bool{}
47		for _, settlement := range settlements {
48			if settlement.Status == "settled" {
49				seen[settlement.Intent] = true
50			}
51		}
52		var gaps []string
53		for _, intent := range intents {
54			if !seen[intent.ID] {
55				gaps = append(gaps, intent.ID)
56			}
57		}
58		sort.Strings(gaps)
59		return gaps
60	}
