1	// Command payflow is the 链上支付与结算编排平台 entry point.
2	package main
3	
4	import (
5		"bytes"
6		"encoding/json"
7		"flag"
8		"fmt"
9		"io"
10		"os"
11	
12		"github.com/gzhysuiioo/payflow-settlement/payflow"
13	)
14	
15	func main() {
16		os.Exit(runCLI(os.Args[1:], os.Stdin, os.Stdout, os.Stderr))
17	}
18	
19	const versionString = "payflow 0.2.0"
20	
21	func runCLI(args []string, stdin io.Reader, stdout, stderr io.Writer) int {
22		if len(args) == 0 {
23			return runDemo(stdout)
24		}
25		switch args[0] {
26		case "demo":
27			return runDemo(stdout)
28		case "version":
29			fmt.Fprintln(stdout, versionString)
30			return 0
31		case "help", "-h", "--help":
32			usage(stdout)
33			return 0
34		case "init":
35			return cmdInit(args[1:], stdin, stdout, stderr)
36		case "submit":
37			return cmdSubmit(args[1:], stdin, stdout, stderr)
38		case "refund":
39			return cmdRefund(args[1:], stdin, stdout, stderr)
40		case "query":
41			return cmdQuery(args[1:], stdout, stderr)
42		case "reconcile":
43			return cmdReconcile(args[1:], stdin, stdout, stderr)
44		default:
45			fmt.Fprintf(stderr, "unknown command %q\n", args[0])
46			usage(stderr)
47			return 2
48		}
49	}
50	
51	func usage(w io.Writer) {
52		fmt.Fprintln(w, "usage: payflow <command> [flags]")
53		fmt.Fprintln(w, "")
54		fmt.Fprintln(w, "commands:")
55		fmt.Fprintln(w, "  init       initialize a ledger with starting balances")
56		fmt.Fprintln(w, "  submit     submit a JSON payment batch against a ledger")
57		fmt.Fprintln(w, "  refund     submit a JSON full-refund batch against a ledger")
58		fmt.Fprintln(w, "  query      print balances, settlement and refund records of a ledger")
59		fmt.Fprintln(w, "  reconcile  reconcile an ordered JSON flow against a ledger")
60		fmt.Fprintln(w, "  demo       run the in-memory settlement demo")
61		fmt.Fprintln(w, "  version    print version")
62		fmt.Fprintln(w, "  help       show this help")
63		fmt.Fprintln(w, "")
64		fmt.Fprintln(w, "ledger flags (init/submit/refund/query/reconcile):")
65		fmt.Fprintln(w, "  -l, --ledger <path>   ledger file path (required)")
66		fmt.Fprintln(w, "  -f, --file <path>     JSON input file (init/submit/refund/reconcile; default: stdin)")
67		fmt.Fprintln(w, "")
68		fmt.Fprintln(w, "reconcile range flags (seq bounds, after < seq <= through; default: full history):")
69		fmt.Fprintln(w, "  --payment-after <n>    payment seq lower bound (exclusive)")
70		fmt.Fprintln(w, "  --payment-through <n>  payment seq upper bound (inclusive)")
71		fmt.Fprintln(w, "  --refund-after <n>     refund seq lower bound (exclusive)")
72		fmt.Fprintln(w, "  --refund-through <n>   refund seq upper bound (inclusive)")
73	}
74	
75	// initRequest 是 init 的输入：{"balances":[...]}。
76	type initRequest struct {
77		Balances []payflow.BalanceInit `json:"balances"`
78	}
79	
80	type errorEnvelope struct {
81		Error struct {
82			Kind    string `json:"kind"`
83			Message string `json:"message"`
84		} `json:"error"`
85	}
86	
87	func failEnvelope(stderr io.Writer, kind, message string) int {
88		env := errorEnvelope{}
89		env.Error.Kind = kind
90		env.Error.Message = message
91		writeJSON(stderr, env)
92		return 1
93	}
94	
95	func failWithError(stderr io.Writer, err error) int {
96		return failEnvelope(stderr, payflow.KindOf(err), err.Error())
97	}
98	
99	func writeJSON(w io.Writer, v any) {
100		data, err := json.MarshalIndent(v, "", "  ")
101		if err != nil {
102			fmt.Fprintf(w, `{"error":{"kind":"storage_error","message":%q}}`+"\n", err.Error())
103			return
104		}
105		w.Write(data)
106		w.Write([]byte("\n"))
107	}
