565					return
566				}
567				if res.Results[0].Status == StatusSettled && i%3 == 0 {
568					_, _ = l.Refund(RefundBatch{Refunds: []RefundRequest{{
569						ID: "r-" + strconv.Itoa(i), SettlementID: id, Reason: "x",
570					}}})
571				}
572			}
573		}()
574	
575		// 对账方：空列表报告（全部缺失）必须始终是某个完整状态的一致快照。
576		for i := 0; i < 200; i++ {
577			rep, err := l.ReconcileFlow(nil)
578			if err != nil {
579				t.Fatalf("reconcile: %v", err)
580			}
581			if int64(len(rep.MissingPayments)) != rep.MaxPaymentSeq {
582				t.Fatalf("payments %d != max seq %d", len(rep.MissingPayments), rep.MaxPaymentSeq)
583			}
584			if int64(len(rep.MissingRefunds)) != rep.MaxRefundSeq {
585				t.Fatalf("refunds %d != max seq %d", len(rep.MissingRefunds), rep.MaxRefundSeq)
586			}
587			// 账本侧净扣款 = 成功付款数 - 成功退款数。
588			var net int64
589			for _, row := range rep.Totals.Ledger {
590				n := new(big.Int)
591				if _, ok := n.SetString(row.NetCharged, 10); !ok {
592					t.Fatalf("bad net %q", row.NetCharged)
593				}
594				net = n.Int64()
595			}
596			if net != rep.MaxPaymentSeq-rep.MaxRefundSeq {
597				t.Fatalf("net=%d want %d", net, rep.MaxPaymentSeq-rep.MaxRefundSeq)
598			}
599		}
600		close(stop)
601		wg.Wait()
602	}
603	
604	// ---- 按成功序号限定核对范围 ----
605	
606	// rangeLedger 构造含 3 笔付款、2 笔退款的账本：
607	// p1(usdc,1003)、p2(usdc,2006)、p3(eth,10)；r1 退 p1、r2 退 p2。
608	func rangeLedger(t *testing.T) *Ledger {
609		t.Helper()
610		path := newTestLedger(t, []BalanceInit{
611			{Account: "aa-1", Asset: "usdc", Balance: 1000000},
612			{Account: "aa-2", Asset: "eth", Balance: 100},
613		})
614		l := openOrFail(t, path)
615		res, err := l.Submit(FeeBatch{FeeBps: 30, Intents: []PaymentIntent{
616			{ID: "p1", Account: "aa-1", Paymaster: "pm", Asset: "usdc", Amount: i64p(1000), Nonce: 1, State: "pending"},
617			{ID: "p2", Account: "aa-1", Paymaster: "pm", Asset: "usdc", Amount: i64p(2000), Nonce: 2, State: "pending"},
618			{ID: "p3", Account: "aa-2", Asset: "eth", Amount: i64p(10), State: "pending"},
619		}})
620		if err != nil {
621			t.Fatalf("submit: %v", err)
622		}
623		for i, want := range []string{StatusSettled, StatusSettled, StatusSettled} {
624			if res.Results[i].Status != want {
625				t.Fatalf("setup payment %d status=%s", i, res.Results[i].Status)
626			}
627		}
628		rr, err := l.Refund(RefundBatch{Refunds: []RefundRequest{
629			{ID: "r1", SettlementID: "p1", Reason: "cancel"},
630			{ID: "r2", SettlementID: "p2", Reason: "cancel"},
631		}})
632		if err != nil {
633			t.Fatalf("refund: %v", err)
634		}
635		for i, want := range []string{StatusRefundSuccess, StatusRefundSuccess} {
636			if rr.Results[i].Status != want {
637				t.Fatalf("setup refund %d status=%s", i, rr.Results[i].Status)
638			}
639		}
640		return l
641	}
