643	func flowEntry(idx int, kind, id, acct, asset string, amount, fee, charged int64, settle string) FlowEntry {
644		return FlowEntry{
645			Index: idx, Kind: kind, ID: id, Account: acct, Asset: asset,
646			Amount: amount, Fee: fee, Charged: charged, SettlementID: settle,
647		}
648	}
