226				Charged      int64  `json:"charged"`
227			} `json:"results"`
228		}
229		if err := json.Unmarshal([]byte(r.out), &res); err != nil {
230			t.Fatal(err)
231		}
232		want := []string{"refunded", "duplicate", "conflict", "already_refunded", "not_found", "not_found", "invalid_parameter"}
233		if len(res.Results) != len(want) {
234			t.Fatalf("got %d results, want %d: %s", len(res.Results), len(want), r.out)
235		}
