245				t.Fatalf("item %d missing trace fields: %+v", i, x)
246			}
247		}
248	
249		// 退款后余额恢复为 2000（全额含手续费）。
250		r = runCLIWith(t, []string{"query", "-l", ledgerPath}, "")
251		var snap struct {
252			Balances []struct {
253				Balance int64 `json:"balance"`
254			} `json:"balances"`
255			Refunds []struct {
256				ID           string `json:"id"`
257				SettlementID string `json:"settlement_id"`
258				Reason       string `json:"reason"`
259				Charged      int64  `json:"charged"`
260			} `json:"refunds"`
261		}
262		if err := json.Unmarshal([]byte(r.out), &snap); err != nil {
263			t.Fatal(err)
264		}
265		if len(snap.Balances) != 1 || snap.Balances[0].Balance != 2000 {
266			t.Fatalf("balance after refund=%+v", snap.Balances)
267		}
268		if len(snap.Refunds) != 1 || snap.Refunds[0].SettlementID != "p1" || snap.Refunds[0].Charged != 1504 {
269			t.Fatalf("query refunds=%+v", snap.Refunds)
270		}
271	
272		// 空列表返回空结果。
273		if r := runCLIWith(t, []string{"refund", "-l", ledgerPath}, `{"refunds":[]}`); r.code != 0 ||
274			strings.TrimSpace(r.out) != "{\n  \"results\": []\n}" {
275			t.Fatalf("empty refund batch: code=%d out=%q err=%s", r.code, r.out, r.err)
276		}
277	
278		// 非法 JSON 走批次级错误信封。
279		if r := runCLIWith(t, []string{"refund", "-l", ledgerPath}, `{bad`); r.code != 1 ||
280			decodeOut(t, r.err)["error"].(map[string]any)["kind"] != "invalid_parameter" {
281			t.Fatalf("bad refund json: code=%d err=%s", r.code, r.err)
282		}
283	
284		// 缺少 -l。
285		if r := runCLIWith(t, []string{"refund"}, `{"refunds":[]}`); r.code != 1 ||
286			decodeOut(t, r.err)["error"].(map[string]any)["kind"] != "invalid_parameter" {
287			t.Fatalf("refund without -l: %+v", r)
288		}
289	
290		// 未初始化账本。
291		missing := t.TempDir() + "/nope.json"
292		if r := runCLIWith(t, []string{"refund", "-l", missing}, `{"refunds":[]}`); r.code != 1 ||
293			decodeOut(t, r.err)["error"].(map[string]any)["kind"] != "ledger_not_initialized" {
